'use strict';
history.scrollRestoration='manual';
const main=document.querySelector('main');
const storageKey='airassist-functional-v1';
const staffCodeKey='airassist-staff-code-v1';
const icon={arrow:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15M13 6l6 6-6 6"/></svg>',plane:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 14 6-2-5-6 2-1 8 6 5-1c3 0 3 3 0 3l-5 1-3 6-2 1 1-7-5 2z"/></svg>',check:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>',info:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 11v6M12 7v1"/></svg>',warning:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 10 17H2zM12 8v5M12 16v1"/></svg>',arrowUp:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>',lock:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/></svg>',chevron:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>',edit:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 16-1 4 4-1L20 7l-3-3zM14 7l3 3"/></svg>',help:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M10 9a2 2 0 0 1 4 0c0 2-2 2-2 4M12 16v1"/></svg>',download:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/></svg>',plug:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 2v5M16 2v5M6 7h12v4a6 6 0 0 1-12 0zM12 17v5"/></svg>'};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function newKey(){if(crypto.randomUUID)return crypto.randomUUID();const a=new Uint8Array(16);crypto.getRandomValues(a);return Array.from(a,x=>x.toString(16).padStart(2,'0')).join('');}
function readSaved(){try{const value=JSON.parse(sessionStorage.getItem(storageKey)||'{}');return value&&typeof value==='object'?value:{};}catch{return {};}}
const saved=readSaved();
const readQueries=AirAssistState.createQueries();
const reviewDrafts=AirAssistState.createDrafts(sessionStorage,'airassist-review-drafts-v1');
const state={booking:null,bookingLoading:false,bookingError:null,bookingGeneration:0,lookup:{reference:String(saved.lookup?.reference||'NZ7K2H'),lastName:String(saved.lookup?.lastName||'Taylor')},draft:{email:String(saved.draft?.email||'alex.taylor@example.com'),reason:['flight_cancelled','schedule_changed','other'].includes(saved.draft?.reason)?saved.draft.reason:'flight_cancelled',details:String(saved.draft?.details||''),requestKey:String(saved.draft?.requestKey||newKey())},acknowledged:false,submitting:false,submitError:null,request:null,creationResult:null,lastRequest:saved.lastRequest||null,track:{reference:String(saved.lastRequest?.reference||''),email:String(saved.lastRequest?.email||'')},trackLoading:false,trackError:null,trackRecord:null,trackGeneration:0,trackAutoAttempted:false,health:null,healthError:false,sapId:'60000002',sapGeneration:0,sapLoading:false,sapError:null,sapRecord:null,receipt:{key:null,loading:false,error:null,status:''},caseLookup:{reference:String(saved.reviewLookup?.reference||saved.lastRequest?.reference||''),email:String(saved.reviewLookup?.email||saved.lastRequest?.email||'')},caseData:null,caseDraft:null,caseLoading:false,caseBusy:false,caseError:null,caseLookupError:null,caseSuccess:'',caseConflict:false,caseGeneration:0,caseAutoAttempted:false,caseDraftRetained:false,caseDraftGuard:false,caseDraftMustSave:false,caseFinancialOwner:'',caseFinancialId:'60000002',caseFinancialNote:'',caseFinancialBusy:false,caseFinancialError:null,casePanels:{},staffCode:readStaffCode(),staffUnlocked:false,staffVerifying:false,staffError:null,staffAutoAttempted:false,queue:null,queueLoading:false,queueError:null,queueFilter:'all'};
const reasons=[['flight_cancelled','Flight cancelled','The airline cancelled my flight.'],['schedule_changed','Schedule changed','My flight time or route changed.'],['other','Other reason','I need help with a different issue.']];
const reasonLabel=value=>reasons.find(([code])=>code===value)?.[1]||String(value||'Not specified');
const currentView=()=>new URLSearchParams(location.search).get('view')||'journey';
function persist(){try{sessionStorage.setItem(storageKey,JSON.stringify({lookup:state.lookup,draft:state.draft,lastRequest:state.lastRequest,reviewLookup:state.caseLookup}));}catch{/* Database submission does not depend on browser draft storage. */}}
function hasMoney(amount,currency){return amount!==null&&amount!==undefined&&typeof amount!=='boolean'&&String(amount).trim()!==''&&Number.isFinite(Number(amount))&&typeof currency==='string'&&/^[A-Z]{3}$/.test(currency.trim());}
function money(amount,currency){if(!hasMoney(amount,currency))return 'Not supplied';try{return new Intl.NumberFormat('en-NZ',{style:'currency',currency:currency.trim(),currencyDisplay:'code',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(amount));}catch{return `${currency.trim()} ${Number(amount).toFixed(2)}`;}}
function dateLabel(date){const d=new Date(`${String(date).slice(0,10)}T12:00:00`);return Number.isNaN(d.getTime())?String(date||'Not supplied'):d.toLocaleDateString('en-NZ',{weekday:'short',day:'numeric',month:'short',year:'numeric'});}
function timestamp(value){const d=new Date(value);return Number.isNaN(d.getTime())?'Not supplied':d.toLocaleString('en-NZ',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit'});}
function amountMarkup(value,currency){if(!hasMoney(value,currency))return 'Not supplied';const code=currency==='NZD'?'NZ$':currency;return `<small>${esc(code)}</small>${Number(value).toLocaleString('en-NZ',{minimumFractionDigits:2,maximumFractionDigits:2})}`;}
async function api(path,{method='GET',body,signal,headers:extraHeaders}={}){const controller=new AbortController();const forwardAbort=()=>controller.abort();if(signal?.aborted)controller.abort();else signal?.addEventListener('abort',forwardAbort,{once:true});const timeout=setTimeout(()=>controller.abort(),15000);const headers={...(body?{'Content-Type':'application/json'}:{}),...(extraHeaders||{})};try{const response=await fetch(path,{method,cache:'no-store',credentials:'same-origin',signal:controller.signal,headers:Object.keys(headers).length?headers:undefined,body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw Object.assign(new Error('The service returned an unreadable response. Please try again.'),{code:'INVALID_RESPONSE'});}if(!response.ok)throw Object.assign(new Error(data.error?.message||'The request could not be completed. Please try again.'),{code:data.error?.code||'REQUEST_FAILED',status:response.status});return data;}catch(error){if(error.name==='AbortError'&&signal?.aborted)throw Object.assign(new Error('Query cancelled.'),{code:'QUERY_CANCELLED'});if(error.name==='AbortError')throw Object.assign(new Error('The service is taking too long to respond. Please try again.'),{code:'NETWORK_TIMEOUT'});if(error instanceof TypeError)throw Object.assign(new Error('We could not reach the service. Check the connection and try again.'),{code:'NETWORK_ERROR'});throw error;}finally{clearTimeout(timeout);signal?.removeEventListener('abort',forwardAbort);}}
const errorBlock=(error,id='')=>error?`<div class="app-error" ${id?`id="${id}"`:''} role="alert">${icon.warning}<div><strong>${esc(error.message||error)}</strong>${error.code==='NETWORK_ERROR'||error.code==='NETWORK_TIMEOUT'?'<p>Your input has been kept. Retry when the service is available.</p>':''}</div></div>`:'';
const loading=(copy)=>`<div class="state-panel" role="status"><span class="loading-dot" aria-hidden="true"></span><span>${esc(copy)}</span></div>`;
const empty=(title,copy,action='')=>`<section class="empty-panel">${icon.info}<h2>${title}</h2><p>${copy}</p>${action}</section>`;
const heading=(title,description,showBooking=true)=>`<section class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${showBooking&&state.booking?`<div class="booking-context"><span>Booking reference</span><strong>${esc(state.booking.reference)}</strong><small>${esc(state.booking.source?.label||'Sample journey')}</small></div>`:''}</section>`;
const stepper=n=>`<div class="flow-steps" aria-label="Refund flow steps">${['Journey','Request details','Review'].map((s,i)=>`${i?'<span class="flow-line" aria-hidden="true"></span>':''}<div class="flow-step ${i<n-1?'complete':i===n-1?'active':''}"><span>${i<n-1?icon.check:i+1}</span>${s}</div>`).join('')}</div>`;
function summary(showValue=true){const b=state.booking;if(!b)return '';return `<div class="form-summary"><div class="summary-header"><span>Booking summary</span><span class="badge sample">Sample journey</span></div><div class="summary-body"><div class="compact-route"><div><strong>${esc(b.fromCode)}</strong><small>${esc(b.fromCity)}</small></div>${icon.plane}<div><strong>${esc(b.toCode)}</strong><small>${esc(b.toCity)}</small></div></div><div class="summary-flight">${esc(b.flight)} · ${esc(dateLabel(b.date))} · ${esc(b.departure)}</div><div class="summary-data"><div><span>Traveller</span><strong>${esc(b.traveller)}</strong></div><div><span>Reference</span><strong>${esc(b.reference)}</strong></div><div><span>Booking channel</span><strong>${b.channel==='direct'?'Direct booking':'Travel agent'}</strong></div></div>${showValue?`<div class="amount-section"><span class="amount-label">Ticket value · sample</span><div class="amount">${amountMarkup(b.ticketValue,b.currency)}</div><p class="fineprint">Refund amount is not determined at this stage.</p></div>`:''}</div></div>`;}
function bookingForm(){return `<div class="booking-lookup"><form id="booking-lookup"><div class="field"><label for="booking-reference">Booking reference</label><input id="booking-reference" name="reference" value="${esc(state.lookup.reference)}"${state.bookingLoading?' disabled':''} maxlength="6" minlength="6" required autocomplete="off" spellcheck="false"></div><div class="field"><label for="booking-lastname">Family name</label><input id="booking-lastname" name="lastName" value="${esc(state.lookup.lastName)}"${state.bookingLoading?' disabled':''} maxlength="100" required autocomplete="off"></div><button class="btn" type="submit"${state.bookingLoading?' disabled':''}>${state.bookingLoading?'Finding booking…':'Find booking'} ${icon.arrow}</button></form><p class="lookup-hint">Sample booking: NZ7K2H / Taylor. Travel-agent example: NZ8T3H / Taylor.</p></div>`;}
function journey(){const b=state.booking;let content='';if(state.bookingLoading)content=loading('Finding your booking…');else if(state.bookingError)content=errorBlock(state.bookingError)+empty('Booking not available','Check the reference and family name, then try again.');else if(!b)content=empty('Find your journey','Enter the sample booking reference and family name above.');else{const direct=b.channel==='direct';content=`${b.flightStatus==='cancelled'?`<div class="alert">${icon.warning}<div><strong>Your flight has been cancelled.</strong><p>You can request a refund for a direct booking below.</p></div><a href="?view=help">View guidance ${icon.arrowUp}</a></div>`:''}<div class="journey-grid"><div><article class="ticket" aria-label="Sample itinerary"><div class="ticket-main"><div class="ticket-top"><span class="flight-heading">OUTBOUND <strong>· ${esc(dateLabel(b.date))}</strong></span><span class="badge cancelled"><i></i>${esc(b.flightStatus==='cancelled'?'Cancelled':b.flightStatus)}</span></div><div class="route"><div><span class="route-code">${esc(b.fromCode)}</span><span class="route-name">${esc(b.fromCity)}</span></div><div class="route-path">${icon.plane}</div><div class="destination"><span class="route-code">${esc(b.toCode)}</span><span class="route-name">${esc(b.toCity)}</span></div></div><div class="time-row"><div><time>${esc(b.departure)}</time><span>Scheduled departure</span></div><div><time>${esc(b.arrival)}</time><span>Scheduled arrival</span></div></div></div><div class="ticket-meta"><div><span class="datum-label">Flight</span><span class="datum-value">${esc(b.flight)}</span></div><div><span class="datum-label">Traveller</span><span class="datum-value">${esc(b.traveller)}</span></div><div><span class="datum-label">Booking channel</span><span class="datum-value">${direct?'Direct booking':'Travel agent'}</span></div></div><div class="ticket-foot"><span>${icon.info}${esc(b.source?.label||'Sample journey')}</span><span>All times are New Zealand time.</span></div></article><details class="ticket-details"><summary>Ticket details ${icon.chevron}</summary><div class="detail-rows"><div>Ticket value<strong>${esc(money(b.ticketValue,b.currency))} · sample</strong></div><div>Journey type<strong>One-way</strong></div><div>Refund eligibility<strong>Review required</strong></div><div>Refund amount<strong>Not determined</strong></div></div></details></div><aside class="action-column"><section class="action-panel"><h2>${direct?'Request a refund':'Contact your travel agent'}</h2><p>${direct?'For tickets booked directly with Air New Zealand.':'The agent handling this ticket is the right contact for refund options.'}</p><div class="amount-section"><span class="amount-label">Ticket value · sample</span><div class="amount">${amountMarkup(b.ticketValue,b.currency)}</div></div><div class="cost-breakdown"><div class="cost-row"><span>Refund amount</span><strong>Awaiting review</strong></div><div class="cost-row"><span>Booking channel</span><strong>${direct?'Direct':'Travel agent'}</strong></div></div>${direct?`<a href="?view=refund" class="btn primary full">Request a refund ${icon.arrow}</a>`:`<a href="?view=help" class="btn primary full">View agent guidance ${icon.arrow}</a>`}<p class="fineprint">${direct?'Application is saved in this prototype. It does not cancel a ticket or issue payment.':'Travel-agent bookings cannot be submitted through this direct-booking flow.'}</p></section><section class="agent-help">${icon.help}<div><h3>Refund support</h3><p>Eligibility, approval and payment are separate steps.</p></div></section></aside></div><div class="note-line">${icon.info}<span>Sample journey data. A saved application is a local prototype record, not an Air New Zealand or SAP refund.</span></div>`;}return heading('Manage your booking','Find your journey and see your refund options.')+bookingForm()+`<div id="booking-response">${content}</div>`;}
function bookingRequired(){return heading('Request a refund','Find your booking before starting a request.',false)+(state.bookingLoading?loading('Finding your booking…'):errorBlock(state.bookingError)+empty('A booking is needed','Look up the booking reference and family name first.','<a class="btn" href="?view=journey">Find booking '+icon.arrow+'</a>'));}
function agentBlocked(){return heading('Contact your travel agent','This booking was made through a travel agent.')+empty('Use your travel agent for this ticket','The direct-booking refund form is unavailable for this booking.','<a class="btn" href="?view=help">View guidance '+icon.arrow+'</a>');}
function refund(){const b=state.booking;if(!b)return bookingRequired();if(b.channel!=='direct')return agentBlocked();return `${heading('Request a refund','Add a reason and your contact details.')}${stepper(2)}<div class="form-grid"><form class="form-sheet" id="refund-form"><section class="form-section"><h2>Why are you requesting a refund?</h2><p>Select the reason that best fits your journey.</p><div class="reason-options">${reasons.map(([code,name,description])=>`<label class="reason-option"><input type="radio" name="reason" value="${code}"${state.draft.reason===code?' checked':''} required><span><strong>${name}</strong><small>${description}</small></span></label>`).join('')}</div><div class="field"><label for="request-details">Additional details <span>Optional</span></label><textarea id="request-details" name="details" maxlength="2000">${esc(state.draft.details)}</textarea></div></section><section class="form-section"><h2>Contact details</h2><div class="contact-line"><div class="known-contact"><span class="datum-label">Traveller</span><strong>${esc(b.traveller)}</strong><small>From sample booking</small></div><div class="field"><label for="request-email">Email address</label><input type="email" id="request-email" name="email" value="${esc(state.draft.email)}" maxlength="254" required autocomplete="email"></div></div></section><div class="form-actions"><a class="btn back" href="?view=journey">← Back to booking</a><button class="btn" type="submit">Review request ${icon.arrow}</button></div></form><aside class="form-aside">${summary()}<div class="side-caption">${icon.info}<p>The application is saved locally in this prototype. The airline has not received or approved it.</p></div></aside></div>`;}
function review(){const b=state.booking;if(!b)return bookingRequired();if(b.channel!=='direct')return agentBlocked();return `${heading('Review your request','Check the details before submitting.')}${stepper(3)}<div class="form-grid"><form class="form-sheet" id="submit-request"><div class="review-heading"><h2>Request details</h2><a class="edit-link" href="?view=refund"${state.submitting?' aria-disabled="true"':''}>Edit ${icon.edit}</a></div><dl class="review-list"><div><dt>Traveller</dt><dd>${esc(b.traveller)}</dd></div><div><dt>Booking reference</dt><dd>${esc(b.reference)}</dd></div><div><dt>Reason</dt><dd>${esc(reasonLabel(state.draft.reason))}</dd></div><div><dt>Email</dt><dd>${esc(state.draft.email)}</dd></div><div><dt>Additional details</dt><dd>${esc(state.draft.details)||'No additional details.'}</dd></div></dl><label class="review-consent"><input id="request-acknowledgment" name="acknowledged" type="checkbox" required${state.acknowledged?' checked':''}${state.submitting?' disabled':''}><span>I understand this saves a prototype application. It does not cancel my ticket, create a SAP refund or confirm approval or payment.</span></label>${errorBlock(state.submitError)}<div class="form-actions"><a class="btn back" href="?view=refund"${state.submitting?' aria-disabled="true"':''}>← Back to details</a><button id="submit-button" class="btn" type="submit"${state.submitting||!state.acknowledged?' disabled':''}>${state.submitting?'Saving request…':state.submitError?'Retry submission':'Submit request'} ${state.submitting?'<span class="button-spinner" aria-hidden="true"></span>':icon.arrow}</button></div><p class="fineprint">Check the acknowledgement to continue. Approval and payment remain separate steps.</p>${state.submitting?'<p role="status" class="fineprint">Saving your application. Please wait.</p>':''}</form><aside class="form-aside">${summary()}<div class="side-caption">${icon.lock}<p>Only enter contact details you want to use for this prototype. Keep the reference and email for tracking.</p></div></aside></div>`;}
function confirmation(){const r=state.request;if(!r){if(state.trackLoading)return heading('Request saved','Loading the saved application.',false)+loading('Retrieving your request…');return heading('Your refund request','A saved application is needed to show a confirmation.',false)+errorBlock(state.trackError)+empty('No submitted request to show','Submit an application or look up a saved request.','<a class="btn" href="?view=track">Track request '+icon.arrow+'</a>');}const created=state.creationResult?.created;const existing=created===false;const title=existing?'Existing application found':created===true?'Request saved':'Saved application';const resultCopy=existing?'Your original application is unchanged.':created===true?'Request saved successfully.':'Your saved application.';return `${heading(title,'Local prototype application.',false)}<section class="success-sheet"><div class="success-mark">${icon.check}</div><h2>${resultCopy}</h2><p>${existing?esc(state.creationResult.message||'An application already exists. The original details below were returned without changes.'):'Keep the reference and email below to view this application again.'}</p><div class="sample-reference"><div><span class="datum-label">Request reference</span><strong>${esc(r.publicReference)}</strong></div><button class="copy-reference" data-copy-reference="${esc(r.publicReference)}" type="button">Copy</button></div><div class="confirmation-detail"><span>Email for tracking</span><strong>${esc(r.email)}</strong></div><div class="confirmation-detail"><span>Saved at</span><strong>${esc(timestamp(r.createdAt))}</strong></div><div class="confirmation-detail"><span>Reason</span><strong>${esc(reasonLabel(r.reason))}</strong></div><div class="confirmation-detail"><span>Additional details</span><strong class="request-inline-details">${esc(r.details)||'No additional details.'}</strong></div><div class="success-next">${icon.info}<div><h3>${esc(r.statusLabel||'Awaiting review')}</h3><p>This is a local prototype application. No request has been sent to the airline or created in SAP, and no refund has been approved or paid.</p></div></div><div class="success-actions"><a class="btn primary" href="?view=track">Track this request ${icon.arrow}</a><a class="btn outline" href="?view=journey">Back to booking</a></div>${receiptAction(r)}</section>`;}
function receiptKey(r){return `${r.publicReference}\u0000${r.email}`;}
function receiptAction(r){const same=state.receipt.key===receiptKey(r);const busy=same&&state.receipt.loading;const error=same?state.receipt.error:null;const status=same?state.receipt.status:'';return `<section class="receipt-section" aria-label="Application receipt"><div class="receipt-row"><button class="receipt-download" data-download-receipt="${esc(r.publicReference)}" type="button" aria-describedby="receipt-caption"${busy?' disabled aria-busy="true"':''}>${busy?'<span class="loading-dot" aria-hidden="true"></span>':icon.download}<span>${busy?'Preparing receipt…':error?'Try download again':'Download receipt'}</span></button><span class="receipt-caption" id="receipt-caption">Local application record · JSON</span></div><p class="receipt-status" role="status"${status?'':' hidden'}>${esc(status)}</p><div class="receipt-error" role="alert"${error?'':' hidden'}>${esc(error?.message||'')}</div></section>`;}
function receiptFilename(header,reference){const fallback=`airassist-receipt-${String(reference).replace(/[^A-Za-z0-9-]/g,'').slice(0,40)||'application'}.json`;let name='';const extended=String(header||'').match(/filename\*\s*=\s*UTF-8''([^;]+)/i);const ordinary=String(header||'').match(/filename\s*=\s*(?:"([^"]+)"|([^;]+))/i);try{name=extended?decodeURIComponent(extended[1].trim()):(ordinary?.[1]||ordinary?.[2]||'').trim();}catch{return fallback;}return /^[A-Za-z0-9][A-Za-z0-9._-]{0,100}\.json$/i.test(name)?name:fallback;}
function updateReceiptControls(){const button=document.querySelector('[data-download-receipt]');if(!button)return;const r=currentView()==='confirmation'?state.request:currentView()==='track'?state.trackRecord:null;if(!r||button.dataset.downloadReceipt!==r.publicReference||state.receipt.key!==receiptKey(r))return;const section=button.closest('.receipt-section');button.disabled=state.receipt.loading;button.setAttribute('aria-busy',String(state.receipt.loading));button.innerHTML=`${state.receipt.loading?'<span class="loading-dot" aria-hidden="true"></span>':icon.download}<span>${state.receipt.loading?'Preparing receipt…':state.receipt.error?'Try download again':'Download receipt'}</span>`;const status=section.querySelector('.receipt-status');status.textContent=state.receipt.status;status.hidden=!state.receipt.status;const error=section.querySelector('.receipt-error');error.textContent=state.receipt.error?.message||'';error.hidden=!state.receipt.error;}
async function downloadReceipt(r){if(state.receipt.loading){toast('A receipt download is being prepared. Please wait.');return;}const key=receiptKey(r);state.receipt={key,loading:true,error:null,status:''};updateReceiptControls();const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch('/api/refund-requests/receipt?'+new URLSearchParams({reference:r.publicReference,email:r.email}),{method:'GET',cache:'no-store',credentials:'same-origin',signal:controller.signal});const content=await response.text();let data;try{data=JSON.parse(content);}catch{throw new Error('The receipt could not be read. Please try again.');}if(!data||typeof data!=='object')throw new Error('The receipt could not be read. Please try again.');if(!response.ok)throw new Error(data.error?.message||'The receipt could not be downloaded. Please try again.');if(data.format!=='airassist-application-receipt'||data.receipt?.publicReference!==r.publicReference||data.receipt?.email!==r.email)throw new Error('The receipt did not match this application. Please try again.');const url=URL.createObjectURL(new Blob([content],{type:'application/json;charset=utf-8'}));try{const link=document.createElement('a');link.href=url;link.download=receiptFilename(response.headers.get('Content-Disposition'),r.publicReference);document.body.appendChild(link);link.click();link.remove();state.receipt.status='Receipt download started.';}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(error){state.receipt.error=new Error(error.name==='AbortError'?'The receipt is taking too long to respond. Please try again.':error instanceof TypeError?'We could not reach the service. Check the connection and try again.':error.message||'The receipt could not be downloaded. Please try again.');}finally{clearTimeout(timeout);state.receipt.loading=false;updateReceiptControls();const button=document.querySelector('[data-download-receipt]');if(button?.dataset.downloadReceipt===r.publicReference&&document.activeElement===document.body)button.focus({preventScroll:true});}}
function requestSummary(r){return `<div class="form-summary"><div class="summary-header"><span>Application details</span><span class="badge sample">Local record</span></div><div class="summary-body"><div class="summary-data"><div><span>Booking</span><strong>${esc(r.bookingReference)}</strong></div><div><span>Family name</span><strong>${esc(r.lastName)}</strong></div><div><span>Reason</span><strong>${esc(reasonLabel(r.reason))}</strong></div><div><span>Contact email</span><strong class="wrap-value">${esc(r.email)}</strong></div></div><div class="amount-section"><span class="amount-label">Ticket value · sample</span><div class="amount">${amountMarkup(r.ticketValue,r.currency)}</div><p class="fineprint">Refund amount is not determined.</p></div>${r.details?`<div class="request-description"><span class="datum-label">Additional details</span><p>${esc(r.details)}</p></div>`:''}</div></div>`;}
function publicReviewHistory(r){const events=Array.isArray(r.review?.events)?r.review.events:[];return events.length?`<details class="public-review-history"><summary>Local event history ${icon.chevron}</summary><ol class="case-audit-list">${events.map(e=>`<li><strong>${esc(e.summary||e.type)}</strong>${e.note?`<p>${esc(e.note)}</p>`:''}<time>${esc(timestamp(e.at))}</time></li>`).join('')}</ol></details>`:'';}
function publicFinancialReference(r){const snapshot=r.review?.financialReference;return snapshot?`<details class="public-review-history public-financial-reference"><summary>SAP reference · ${esc(snapshot.documentId)} ${icon.chevron}</summary><p>${esc(snapshot.source?.label||'Read-only SAP response')} · ${esc(timestamp(snapshot.capturedAt))}</p><p>Demonstration reference only. Booking match is not verified, payment verification is not performed and refund eligibility is not assessed.</p></details>`:'';}
function requestTimeline(r){const review=r.review;const reviewState=review?.state||'not_started';const hasReview=reviewState!=='not_started';const queued=reviewState==='queued';const missing=Array.isArray(review?.missingItems)?review.missingItems:[];return `<ol class="timeline"><li><span class="timeline-mark">${icon.check}</span><div><h3>Application saved</h3><p>Your application is stored in the prototype database.</p><time>${esc(timestamp(r.createdAt))}</time></div></li><li class="${hasReview?'':'pending'}"><span class="timeline-mark ${hasReview?'':'pending'}">${hasReview?icon.check:'<i></i>'}</span><div><h3>${hasReview?'Review recorded':'Evidence review'}${hasReview?'':'<span class="timeline-label">Not reviewed</span>'}</h3><p>${hasReview?esc(review.routeLabel||'The local review has been recorded.'):'Evidence and refund rules have not been reviewed yet.'}</p>${hasReview&&missing.length?`<div class="tracking-review-note"><h3>Checks still needed</h3><ul>${missing.map(item=>`<li>${esc(typeof item==='string'?item:item.label||item.id||'Review evidence')}</li>`).join('')}</ul></div>`:''}</div></li><li class="${queued?'':'pending'}"><span class="timeline-mark ${queued?'':'pending'}">${queued?icon.check:'<i></i>'}</span><div><h3>${queued?'Sent for review':'Review queue'}${queued?'':'<span class="timeline-label">Not sent</span>'}</h3><p>${queued?`${esc(review.queue||'Local review queue')} · ${esc(review.ownerRole||'Local reviewer')}.`:'A complete saved review is needed before local handoff.'}</p>${queued?`<time>${esc(timestamp(r.updatedAt))}</time>`:''}</div></li></ol>${publicReviewHistory(r)}${publicFinancialReference(r)}<p class="tracking-limit">Refund amount, airline approval and payment remain undetermined.</p>`;}
function track(){const r=state.trackRecord;return `${heading('Track your request','Use the saved reference and email to find your application.',false)}<div class="lookup-panel"><form id="track-form"><div class="field"><label for="track-reference">Request reference</label><input id="track-reference" name="reference" value="${esc(state.track.reference)}"${state.trackLoading?' disabled':''} required maxlength="40" autocomplete="off" spellcheck="false" placeholder="AF-…"></div><div class="field"><label for="track-email">Email address</label><input id="track-email" name="email" type="email" value="${esc(state.track.email)}"${state.trackLoading?' disabled':''} required maxlength="254" autocomplete="email" placeholder="Email used for the request"></div><button class="btn" type="submit"${state.trackLoading?' disabled':''}>${state.trackLoading?'Finding request…':'Find request'} ${icon.arrow}</button></form>${state.lastRequest?`<button class="use-saved-request" id="use-saved-request" type="button"${state.trackLoading?' disabled':''}>Use last saved request</button>`:''}</div><div id="track-response">${errorBlock(state.trackError)}${state.trackLoading?loading('Retrieving the application…'):r?`<div class="tracking-grid" id="track-results"><div><section class="tracking-sheet"><div class="tracking-top"><div><span class="datum-label">Request reference</span><strong>${esc(r.publicReference)}</strong></div><span class="badge ${r.status==='information_needed'?'cancelled':'neutral'}">${esc(r.statusLabel||'Received · awaiting review')}</span></div><div class="tracking-content">${requestTimeline(r)}</div><div class="tracking-foot"><div><span class="datum-label">Booking</span><strong>${esc(r.bookingReference)}</strong></div><div><span class="datum-label">Last recorded update</span><strong>${esc(timestamp(r.updatedAt))}</strong></div></div>${receiptAction(r)}</section><div class="source-note">${icon.info}<span>${esc(r.source?.label||'Local prototype application')}. SAP document: ${r.sapCreditMemoRequestId?esc(r.sapCreditMemoRequestId):'not created'}.</span></div></div><aside class="tracking-aside">${requestSummary(r)}<section class="support-box"><h3>Keep your reference</h3><p>The reference and the email used for this application are needed to return to it.</p><a href="?view=help">Help &amp; guidance ${icon.arrowUp}</a></section></aside></div>`:!state.trackError?empty('No request selected','Submit an application first, or enter a saved reference and email above.','<a class="btn outline" href="?view=journey">Manage booking '+icon.arrow+'</a>'):''}</div>`;}
const reviewStateLabels={not_started:'Not started',prepared:'Prepared',queued:'Queued'};
const queueFilters=[['all','All'],['not_started','Not started'],['prepared','Prepared'],['queued','Queued']];
function readStaffCode(){try{return String(sessionStorage.getItem(staffCodeKey)||'');}catch{return '';}}
function writeStaffCode(code){try{sessionStorage.setItem(staffCodeKey,code);}catch{/* Unlocking does not depend on browser storage. */}}
function clearStaffCode(){try{sessionStorage.removeItem(staffCodeKey);}catch{/* The lock state is independent of storage. */}}
function staffGate(){return `${heading('Staff tools','Enter the staff access code to open the local review tools.',false)}<div class="staff-gate"><form id="staff-gate-form"><div class="field"><label for="staff-code">Staff access code</label><input id="staff-code" name="code" type="password" value="${esc(state.staffCode)}" maxlength="200" autocomplete="off" spellcheck="false"${state.staffVerifying?' disabled':''} required><p class="hint">Shown in the server terminal at startup</p></div>${errorBlock(state.staffError,'staff-gate-error')}<div class="form-actions"><button class="btn" type="submit"${state.staffVerifying?' disabled':''}>${state.staffVerifying?'Checking code…':'Unlock staff tools'} ${icon.lock}</button></div></form></div>`;}
function queueRow(c){const selected=state.caseLookup.reference===c.publicReference&&state.caseLookup.email===c.email;const stateLabel=reviewStateLabels[c.reviewState]||reviewStateLabels.not_started;return `<button class="queue-item" type="button" data-queue-reference="${esc(c.publicReference)}" aria-pressed="${selected}"><strong>${esc(c.publicReference)}</strong><span>${esc(reasonLabel(c.reason))}</span><span class="badge ${c.reviewState==='queued'?'green':'neutral'}">${esc(stateLabel)}</span><small>${esc(c.triage?.queue||'No queue')} · ${esc(timestamp(c.updatedAt))}</small></button>`;}
function queueSelect(cases){return `<div class="queue-select"><label for="queue-select">Open a case</label><select id="queue-select"><option value="">Select a case…</option>${cases.map(c=>`<option value="${esc(c.publicReference)}">${esc(c.publicReference)} · ${esc(reasonLabel(c.reason))} · ${esc(reviewStateLabels[c.reviewState]||reviewStateLabels.not_started)}</option>`).join('')}</select></div>`;}
function queuePanel(){const cases=Array.isArray(state.queue)?state.queue:[];const tabs=queueFilters.map(([value,label])=>`<button type="button" class="queue-filter" data-queue-filter="${value}" aria-pressed="${state.queueFilter===value}">${esc(label)}</button>`).join('');let body;if(state.queueLoading)body='<p class="queue-empty" role="status">Loading the case queue…</p>';else if(state.queueError)body=errorBlock(state.queueError,'queue-error');else if(!cases.length)body='<p class="queue-empty">No cases yet</p>';else body=`<div class="queue-list">${cases.map(queueRow).join('')}</div>${queueSelect(cases)}`;return `<section class="case-queue" aria-label="Case queue"><div class="queue-heading"><div><h2>Case queue</h2><small>${cases.length} ${cases.length===1?'case':'cases'}</small></div><button class="queue-refresh" type="button" id="queue-refresh"${state.queueLoading?' disabled':''}>${state.queueLoading?'Refreshing…':'Refresh'}</button></div><div class="queue-filters" role="group" aria-label="Filter cases by review state">${tabs}</div>${body}</section>`;}
function openQueueCase(reference){const c=(Array.isArray(state.queue)?state.queue:[]).find(item=>item.publicReference===reference);if(!c)return false;state.caseLookup={reference:c.publicReference,email:c.email};persist();return loadCase();}
function lockStaff(error=null){readQueries.cancel('queue');state.staffUnlocked=false;state.staffCode='';state.staffVerifying=false;state.queue=null;state.queueLoading=false;state.queueError=null;state.staffError=error;clearStaffCode();if(['staff','financial'].includes(currentView()))render();}
async function requestQueue({verifying=false}={}){const code=state.staffCode.trim();if(!code)return;const ticket=readQueries.start('queue',{state:state.queueFilter});state.queueLoading=true;if(verifying)state.staffVerifying=true;state.queueError=null;if(verifying)state.staffError=null;render();try{const suffix=state.queueFilter==='all'?'':'?'+new URLSearchParams({state:state.queueFilter});const data=await api('/api/staff/queue'+suffix,{signal:ticket.signal,headers:{'X-Staff-Code':code}});if(!ticket.current())return;state.queue=Array.isArray(data.cases)?data.cases:[];state.staffUnlocked=true;state.staffError=null;state.staffAutoAttempted=true;writeStaffCode(code);}catch(error){if(!ticket.current())return;if(error.status===401||error.code==='STAFF_UNAUTHORIZED'){lockStaff(new Error(verifying?'That staff access code was not accepted. Check the code shown in the server terminal and try again.':'Your staff access code is no longer valid. Enter it again to open the review tools.'));}else state.queueError=error;}finally{if(ticket.current()){state.queueLoading=false;state.staffVerifying=false;ticket.finish();if(['staff','financial'].includes(currentView())){render();if(verifying&&!state.staffUnlocked&&state.staffError)focusResult('#staff-code');}}}}
function bindQueue(){document.querySelectorAll('.queue-filter').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.queueFilter;if(!value||value===state.queueFilter)return;state.queueFilter=value;requestQueue();}));document.querySelector('#queue-refresh')?.addEventListener('click',()=>requestQueue());document.querySelectorAll('.queue-item').forEach(row=>row.addEventListener('click',()=>{if(row.dataset.queueReference)openQueueCase(row.dataset.queueReference);}));document.querySelector('#queue-select')?.addEventListener('change',event=>{if(event.target.value)openQueueCase(event.target.value);});}
function operationsTabs(view){return `<nav class="operations-tabs" aria-label="Review workspaces"><a href="?view=staff"${view==='staff'?' aria-current="page"':''}>Case review</a><a href="?view=financial"${view==='financial'?' aria-current="page"':''}>SAP financial reference</a><button class="staff-lock" type="button" id="lock-staff">Lock staff tools</button></nav>`;}
function caseLookupForm(){return `<div class="lookup-panel"><form id="case-lookup"><div class="field"><label for="case-reference">Application reference</label><input id="case-reference" name="reference" value="${esc(state.caseLookup.reference)}"${state.caseBusy||state.caseFinancialBusy||state.caseLoading?' disabled':''} maxlength="40" required autocomplete="off" spellcheck="false" placeholder="AF-…"></div><div class="field"><label for="case-email">Application email</label><input id="case-email" name="email" type="email" value="${esc(state.caseLookup.email)}"${state.caseBusy||state.caseFinancialBusy||state.caseLoading?' disabled':''} maxlength="254" required autocomplete="off" placeholder="Email used for the application"></div><button class="btn" type="submit"${state.caseLoading||state.caseBusy||state.caseFinancialBusy?' disabled':''}>${state.caseLoading?'Finding case…':'Find case'} ${icon.arrow}</button></form>${state.lastRequest?`<button class="use-saved-request" id="use-last-case" type="button"${state.caseBusy||state.caseFinancialBusy||state.caseLoading?' disabled':''}>Use last saved request</button>`:''}</div>`;}
function reviewDraftFrom(c,note=''){return {version:c.version,checks:{paymentEvidenceReviewed:c.checks.paymentEvidenceReviewed===true,refundRulesReviewed:c.checks.refundRulesReviewed===true,supportingDetailsReviewed:c.checks.supportingDetailsReviewed===true},paymentReference:String(c.paymentReference||''),specialistRequired:c.specialistRequired===true,note};}
function caseDraftChanged(){const c=state.caseData,d=state.caseDraft;if(!c||!d)return false;return Object.keys(d.checks).some(key=>d.checks[key]!==c.checks[key])||d.paymentReference!==String(c.paymentReference||'')||d.specialistRequired!==(c.specialistRequired===true);}
function caseOverview(c){const r=c.request,b=c.booking;return `<div class="case-section case-overview compact-case-overview"><div class="case-summary-person"><span class="case-kicker">Traveller</span><h3>${esc(b.traveller)}</h3><p>${esc(r.email)}</p><span class="case-reason">${esc(reasonLabel(r.reason))}</span></div><div class="case-summary-trip"><div class="case-route">${esc(b.fromCode)} ${icon.plane} ${esc(b.toCode)}</div><p class="case-flight">${esc(b.flight)} · ${esc(dateLabel(b.date))}</p><p>${esc(r.bookingReference)} · ${b.channel==='direct'?'Direct booking':'Travel agent'} · ${esc(b.flightStatus)}</p></div><details class="case-panel case-application-details" data-case-panel="application"${state.casePanels.application?' open':''}><summary><span>Application details</span>${icon.chevron}</summary><div class="case-panel-content"><dl class="case-summary-data"><div><dt>Submitted</dt><dd>${esc(timestamp(r.createdAt))}</dd></div><div><dt>Ticket value</dt><dd>${esc(money(b.ticketValue,b.currency))}</dd></div><div><dt>Refund amount</dt><dd>Undetermined</dd></div></dl>${r.details?`<p class="case-detail-text">${esc(r.details)}</p>`:''}</div></details><p class="case-summary-limit">${esc(b.source?.label||'Sample journey')}. Ticket value is synthetic; refund amount is undetermined.</p></div>`;}
function caseChecklist(c){const statusLabel={available:'Available',missing:'Missing',recorded:'Recorded',not_required:'Not required'};const missing=c.checklist.filter(item=>item.required&&item.status==='missing').length;return `<section class="case-section case-checklist-panel"><details class="case-panel" data-case-panel="checklist"${state.casePanels.checklist?' open':''}><summary><span><strong>Saved evidence checklist</strong><small>${missing?`${missing} required ${missing===1?'item':'items'} missing`:'Required evidence recorded'}</small></span>${icon.chevron}</summary><div class="case-panel-content"><ul class="evidence-list">${c.checklist.map(item=>`<li class="${item.status==='missing'?'missing':''}">${item.status==='missing'?icon.warning:icon.check}<div><strong>${esc(item.label)}</strong><small>${esc(item.source)}${item.required?' · Required':''}</small></div><span class="badge ${item.status==='missing'?'cancelled':'neutral'}">${esc(statusLabel[item.status]||item.status)}</span></li>`).join('')}</ul></div></details></section>`;}
function caseReviewForm(c){const d=state.caseDraft,queued=c.reviewState==='queued',busy=state.caseBusy||state.caseFinancialBusy,guard=state.caseDraftGuard;const supportingRequired=c.request.reason==='other'||Boolean(c.request.details?.trim());return `<div class="case-review-main"><form class="case-section local-action-form" id="case-review-form"><div class="case-form-heading"><h3>${queued?'Reopen review':'Review the evidence'}</h3><span class="case-form-step">${queued?'Queued review':'Checks and routing'}</span></div>${queued?'<p class="case-form-copy">Add a reason to reopen this queued application before changing evidence or routing.</p>':'<p class="case-form-copy">Record the evidence checked. Manual review entries do not approve a refund.</p>'}${reviewDraftBanner(c)}<fieldset class="review-evidence-controls"${busy||queued||guard?' disabled':''}><legend>Evidence checks</legend><div class="review-check-grid"><div class="review-payment-group"><label class="evidence-control"><input name="paymentEvidenceReviewed" type="checkbox"${d.checks.paymentEvidenceReviewed?' checked':''}><span><strong>Payment evidence reviewed</strong><small>Record the evidence reference.</small></span></label><div class="field payment-reference-field"><label for="case-payment-reference">Payment evidence reference</label><input id="case-payment-reference" name="paymentReference" value="${esc(d.paymentReference)}" maxlength="80"${d.checks.paymentEvidenceReviewed?' required':''} autocomplete="off" placeholder="Evidence reference"><p class="hint">Manual reference; a SAP number is not proof of payment for this booking.</p></div></div><div class="review-rules-group"><label class="evidence-control"><input name="refundRulesReviewed" type="checkbox"${d.checks.refundRulesReviewed?' checked':''}><span><strong>Refund rules reviewed</strong><small>Eligibility and amount still require a decision.</small></span></label><label class="evidence-control"><input name="supportingDetailsReviewed" type="checkbox"${d.checks.supportingDetailsReviewed?' checked':''}><span><strong>Supporting details reviewed</strong><small>${supportingRequired?'Required for this application.':'Optional for this application reason.'}</small></span></label></div></div></fieldset><fieldset class="review-route-controls"${busy||queued||guard?' disabled':''}><legend>Review route</legend><label class="evidence-control specialist-control"><input name="specialistRequired" type="checkbox"${d.specialistRequired?' checked':''}><span><strong>Specialist review required</strong><small>Send to a specialist after required evidence is complete.</small></span></label></fieldset><div class="field review-note-field"><label for="case-note"><span class="review-note-title">${queued?'Reopening note':'Review note'}</span> <span>Required</span></label><textarea id="case-note" name="note" maxlength="1000" required${busy||guard?' disabled':''} placeholder="Record what was checked and why this route is appropriate.">${esc(d.note)}</textarea></div>${errorBlock(state.caseError)}${state.caseSuccess?`<p class="review-saved" role="status">${esc(state.caseSuccess)}</p>`:''}<p class="case-draft-warning"${hasUnsavedReview()?'':' hidden'}>Routing above reflects the last saved review. Save these changes to update it.</p></form><div class="case-action-row case-action-rail" aria-label="Local review actions"><div class="case-action-status"><strong id="case-action-status" role="status">${esc(reviewActionStatus(c))}</strong><p id="case-action-message">${esc(reviewActionMessage(c))}</p></div><div class="case-action-buttons">${queued?`<button class="btn" form="case-review-form" data-case-action="reopen" type="submit"${busy||guard?' disabled':''}>${busy?'Reopening…':'Reopen review'} ${icon.arrow}</button>`:`<button class="btn" form="case-review-form" data-case-action="save_review" type="submit"${busy||guard?' disabled':''}>${busy?'Saving…':state.caseConflict?'Save updated review':'Save review'} ${icon.arrow}</button><button class="btn outline case-handoff-button" data-case-action="handoff" type="button"${busy||guard||state.caseDraftMustSave||!c.triage.readyForHandoff||caseDraftChanged()?' disabled':''}>Send to ${c.triage.route==='complex'?'specialist':'standard'} queue</button>`}</div></div></div>`;}
function caseHistory(c){return `<section class="case-section case-history-panel"><details class="case-panel" data-case-panel="history"${state.casePanels.history?' open':''}><summary><span><strong>Review history</strong><small>${c.events.length} saved ${c.events.length===1?'event':'events'}</small></span>${icon.chevron}</summary><div class="case-panel-content">${c.events.length?`<ol class="case-audit-list">${c.events.map(event=>`<li><strong>${esc(event.summary||event.type)}</strong>${event.note?`<p>${esc(event.note)}</p>`:''}<time>${esc(timestamp(event.at))}${event.queue?` · ${esc(event.queue)}`:''}</time></li>`).join('')}</ol>`:'<p class="case-form-copy">No review event has been recorded.</p>'}</div></details></section>`;}
function staff(){if(!state.staffUnlocked)return staffGate();const c=state.caseData;const localState=c?(c.reviewState==='queued'?'Queued for local review':c.triage.readyForHandoff?'Prepared · ready to route':'Preparation incomplete'):'';return `${heading('Review a refund request','Check the evidence, save the review and assign the next step.',false)}${operationsTabs('staff')}${queuePanel()}${caseLookupForm()}${errorBlock(state.caseLookupError,'case-lookup-error')}${state.caseLoading?loading('Retrieving the application and review…'):c?`<section class="case-sheet compact-case-sheet" id="case-results"><div class="case-head"><div><h2>${esc(c.request.publicReference)}</h2><p>Saved review · Version ${esc(c.version)}</p></div><span class="badge ${c.triage.readyForHandoff?'green':'neutral'}">${esc(localState)}</span></div>${caseOverview(c)}${caseRoutingSummary(c)}<div class="case-review-grid"><aside class="case-review-context" aria-label="Saved case context">${caseChecklist(c)}${caseFinancialReference(c)}${caseHistory(c)}</aside>${caseReviewForm(c)}</div><div class="case-local-note">Local prototype review. Airline approval, refund amount and payment remain undetermined. No SAP document is created.</div></section>`:!state.caseLookupError?empty('Select an application','Use its reference and email to open the local case. Add a SAP financial reference within the case when needed.'):''}`;}
function caseRoutingSummary(c){return `<section class="case-routing-summary ${esc(c.triage.route==='information_needed'?'information-needed':c.triage.route)}" aria-label="Saved review routing"><div><span class="case-kicker">Saved next step</span><strong>${esc(c.triage.label)}</strong><p>${c.triage.readyForHandoff?`${c.reviewState==='queued'?'Assigned':'Proposed'}: ${esc(c.triage.queue)} · ${esc(c.triage.ownerRole)}`:'Complete the required evidence, then save the review before handoff.'}</p></div><div class="case-routing-reasons"><ul>${c.triage.reasons.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul><p>Local preparation rules · ${esc(c.triage.ruleVersion)}. This is not an airline eligibility decision.</p></div></section>`;}
function reviewActionStatus(c){return state.caseBusy||state.caseFinancialBusy?'Updating local case…':state.caseDraftGuard?'Review retained draft':c.reviewState==='queued'?'Queued · reopen to edit':hasUnsavedReview()?'Unsaved changes':c.triage.readyForHandoff?'Saved · ready to route':'Saved · evidence incomplete';}
function reviewActionMessage(c){return state.caseDraftGuard?'Keep or discard the retained draft before continuing.':c.reviewState==='queued'?`${c.triage.queue} · Version ${c.version}. Add a reopening note to edit.`:hasUnsavedReview()?'Save changes before sending this case to a queue.':c.triage.readyForHandoff?`${c.triage.queue} · Version ${c.version}. Handoff records a local queue only.`:`Version ${c.version}. Complete required checks and add a review note.`;}
function hasUnsavedReview(){return Boolean(state.caseDraft&&(caseDraftChanged()||state.caseDraft.note.trim()||state.caseDraftMustSave));}
function retainReviewDraft(){if(!state.caseData||!state.caseDraft||state.caseDraftGuard)return;if(caseDraftChanged()||state.caseDraft.note.trim()){reviewDrafts.save(state.caseData,state.caseDraft);state.caseDraftRetained=true;state.caseDraftMustSave=true;}else{reviewDrafts.discard(state.caseData);state.caseDraftRetained=false;state.caseDraftMustSave=false;}updateReviewDraftUI();}
function syncCaseFinancialOwner(c){const key=JSON.stringify([c.request.publicReference.toUpperCase(),c.request.email.trim().toLowerCase()]);if(state.caseFinancialOwner!==key){state.caseFinancialOwner=key;state.casePanels={};state.caseFinancialId='60000002';state.caseFinancialNote='';state.caseFinancialError=null;}}
function restoreReviewDraft(c,previous=null){syncCaseFinancialOwner(c);const recovered=previous?{draft:previous,versionMismatch:previous.version!==c.version}:reviewDrafts.restore(c);state.caseDraft=recovered?recovered.draft:reviewDraftFrom(c);state.caseDraftRetained=Boolean(recovered);state.caseDraftGuard=Boolean(recovered?.versionMismatch);state.caseDraftMustSave=Boolean(recovered);state.caseConflict=state.caseDraftGuard;}
function reviewDraftBanner(c){return `<div class="review-draft-banner"${state.caseDraftRetained?'':' hidden'}><div><strong>${state.caseDraftGuard?'The saved review changed. Check this retained draft.':'Unsaved review draft retained in this browser.'}</strong><p>${state.caseDraftGuard?`Draft version ${esc(state.caseDraft.version)} · saved version ${esc(c.version)}. Compare the entries with the current checklist and history before keeping them.`:'This draft has not been saved to the case. Reloading does not submit it.'}</p></div><div class="review-draft-actions">${state.caseDraftGuard?'<button type="button" id="keep-review-draft">Keep and review these entries</button>':''}<button type="button" id="discard-review-draft">Discard local draft</button></div></div>`;}
function updateReviewDraftUI(){const banner=document.querySelector('.review-draft-banner');if(banner&&!state.caseDraftGuard)banner.hidden=!state.caseDraftRetained;const handoff=document.querySelector('.case-handoff-button');if(handoff)handoff.disabled=state.caseBusy||state.caseFinancialBusy||state.caseDraftGuard||state.caseDraftMustSave||!state.caseData?.triage.readyForHandoff||caseDraftChanged();const warning=document.querySelector('.case-draft-warning');if(warning)warning.hidden=!hasUnsavedReview();const financial=document.querySelector('#case-financial-submit');if(financial)financial.disabled=state.caseFinancialBusy||state.caseBusy||state.caseDraftGuard||hasUnsavedReview()||state.caseData?.reviewState==='queued';const blocked=document.querySelector('.case-financial-draft-warning');if(blocked)blocked.hidden=!hasUnsavedReview()&&!state.caseDraftGuard;const actionStatus=document.querySelector('#case-action-status');if(actionStatus&&state.caseData)actionStatus.textContent=reviewActionStatus(state.caseData);const actionMessage=document.querySelector('#case-action-message');if(actionMessage&&state.caseData)actionMessage.textContent=reviewActionMessage(state.caseData);}
function captureCaseDraft(form){if(!state.caseDraft||state.caseDraftGuard)return;const d=state.caseDraft;if(state.caseData?.reviewState!=='queued'){for(const key of ['paymentEvidenceReviewed','refundRulesReviewed','supportingDetailsReviewed'])d.checks[key]=form.elements[key].checked;d.paymentReference=form.elements.paymentReference.value;d.specialistRequired=form.elements.specialistRequired.checked;form.elements.paymentReference.required=d.checks.paymentEvidenceReviewed;}d.note=form.elements.note.value;retainReviewDraft();}
function discardReviewDraft(){if(!state.caseData)return;reviewDrafts.discard(state.caseData);state.caseDraft=reviewDraftFrom(state.caseData);state.caseDraftRetained=false;state.caseDraftGuard=false;state.caseDraftMustSave=false;state.caseConflict=false;state.caseError=null;render();focusResult('#case-note');}
function keepReviewDraft(){if(!state.caseData||!state.caseDraft)return;state.caseDraft.version=state.caseData.version;state.caseDraftGuard=false;state.caseConflict=false;state.caseDraftMustSave=true;reviewDrafts.save(state.caseData,state.caseDraft);render();focusResult('#case-note');}
function bindCaseForms(){const panelOwner=state.caseFinancialOwner;document.querySelectorAll('[data-case-panel]').forEach(panel=>{panel.addEventListener('toggle',()=>{if(panelOwner===state.caseFinancialOwner)state.casePanels[panel.dataset.casePanel]=panel.open;});});const lookup=document.querySelector('#case-lookup');if(lookup){lookup.addEventListener('input',()=>{readQueries.cancel('case');state.caseLoading=false;state.caseLookup.reference=lookup.elements.reference.value;state.caseLookup.email=lookup.elements.email.value;state.caseData=null;state.caseDraft=null;state.caseLookupError=null;state.caseError=null;state.caseAutoAttempted=true;persist();document.querySelector('#case-results')?.setAttribute('hidden','');document.querySelector('#case-lookup-error')?.setAttribute('hidden','');});lookup.addEventListener('submit',event=>{event.preventDefault();state.caseLookup={reference:lookup.elements.reference.value.trim().toUpperCase(),email:lookup.elements.email.value.trim()};persist();loadCase()});}document.querySelector('#use-last-case')?.addEventListener('click',()=>{if(state.caseLoading||state.caseBusy||state.caseFinancialBusy)return;state.caseLookup={...state.lastRequest};persist();loadCase()});document.querySelector('.case-handoff-button')?.addEventListener('click',()=>submitCaseAction('handoff'));const form=document.querySelector('#case-review-form');if(form){form.addEventListener('input',()=>captureCaseDraft(form));form.addEventListener('change',()=>captureCaseDraft(form));form.addEventListener('submit',event=>{event.preventDefault();captureCaseDraft(form);submitCaseAction(event.submitter?.dataset.caseAction||'save_review')});}document.querySelector('#discard-review-draft')?.addEventListener('click',discardReviewDraft);document.querySelector('#keep-review-draft')?.addEventListener('click',keepReviewDraft);const financial=document.querySelector('#case-financial-form');if(financial){financial.addEventListener('input',()=>{state.caseFinancialId=financial.elements.documentId.value;state.caseFinancialNote=financial.elements.note.value;state.caseFinancialError=null;document.querySelector('#case-financial-error')?.setAttribute('hidden','');});financial.addEventListener('submit',event=>{event.preventDefault();state.caseFinancialId=financial.elements.documentId.value.trim();state.caseFinancialNote=financial.elements.note.value.trim();captureCaseFinancialReference();});}}
async function loadCase({focus=true,preserveDraft=false}={}){if(state.caseBusy||state.caseFinancialBusy)return;const draft=preserveDraft?state.caseDraft:null;const ticket=readQueries.start('case',{reference:state.caseLookup.reference.trim().toUpperCase(),email:state.caseLookup.email.trim()});state.caseLoading=true;state.caseLookupError=null;state.caseError=null;state.caseAutoAttempted=true;if(!preserveDraft){state.caseData=null;state.caseDraft=null;state.caseSuccess='';state.caseConflict=false;}render();try{const data=await api('/api/review-cases?'+new URLSearchParams(ticket.query),{signal:ticket.signal});if(!ticket.current())return false;state.caseData=data.case;restoreReviewDraft(data.case,draft);return true;}catch(error){if(ticket.current())state.caseLookupError=error;return false;}finally{if(ticket.current()){state.caseLoading=false;ticket.finish();if(currentView()==='staff'){render();if(focus)focusResult(state.caseLookupError?'#case-lookup-error':'.case-head');}}}}
function sameCase(a,b){return Boolean(a?.request&&b?.request&&a.request.publicReference===b.request.publicReference&&a.request.email.trim().toLowerCase()===b.request.email.trim().toLowerCase());}
function applyCase(c){const selected=sameCase(state.caseData,c);if(selected){state.caseData=c;syncCaseFinancialOwner(c);}if(state.request?.publicReference===c.request.publicReference&&state.request.email===c.request.email)state.request=c.request;if(state.trackRecord?.publicReference===c.request.publicReference&&state.trackRecord.email===c.request.email)state.trackRecord=c.request;if(state.track.reference===c.request.publicReference&&state.track.email.trim().toLowerCase()===c.request.email.trim().toLowerCase())state.trackAutoAttempted=false;return selected;}
async function submitCaseAction(action){if(state.caseBusy||state.caseFinancialBusy||!state.caseData||!state.caseDraft)return;if(!['save_review','handoff','reopen'].includes(action))return;const d=state.caseDraft,c=state.caseData;if(state.caseDraftGuard){state.caseError=new Error('Check the retained draft, then keep or discard it before continuing.');render();return;}if(action==='handoff'&&(state.caseDraftMustSave||caseDraftChanged()||d.note.trim()||!c.triage.readyForHandoff)){state.caseError=new Error('Save the current review before sending it to the local queue.');render();return;}const actionNote=action==='handoff'?String(c.note||c.reviewNote||'').trim():d.note.trim();if(!actionNote){state.caseError=new Error(action==='handoff'?'Save a review note before sending this application to the local queue.':'Add a review note before continuing.');render();focusResult('#case-note');return;}state.caseBusy=true;state.caseError=null;state.caseSuccess='';render();try{const evidence=action==='reopen'?reviewDraftFrom(c):d;const data=await api('/api/review-cases',{method:'POST',body:{reference:c.request.publicReference,email:c.request.email,version:d.version,checks:evidence.checks,paymentReference:evidence.paymentReference.trim(),specialistRequired:evidence.specialistRequired,note:actionNote,action}});reviewDrafts.discard(c);const selected=applyCase(data.case);if(!selected)return;state.caseDraft=reviewDraftFrom(data.case);state.caseDraftRetained=false;state.caseDraftGuard=false;state.caseDraftMustSave=false;state.caseConflict=false;state.caseSuccess=action==='handoff'?'Application placed in the local review queue. No refund approval or payment was recorded.':action==='reopen'?'Local review reopened. Evidence and routing can now be updated.':'Local review saved. Checklist and routing have been updated.';}catch(error){if(!sameCase(state.caseData,c))return;state.caseError=error;if(error.status===409&&['REVIEW_VERSION_CONFLICT','VERSION_CONFLICT'].includes(error.code)){state.caseBusy=false;const refreshed=await loadCase({focus:false,preserveDraft:true});state.caseError=refreshed?null:new Error('The review changed, but the latest case could not be loaded. Use Find case to reload before retrying.');}}finally{state.caseBusy=false;if(currentView()==='staff'){render();if(sameCase(state.caseData,c))focusResult(state.caseError?'.local-action-form .app-error':'.case-head');}}}
function caseFinancialReference(c){const snapshot=c.financialReference;const r=snapshot?.record;const locked=c.reviewState==='queued';const blocked=hasUnsavedReview()||state.caseDraftGuard;const busy=state.caseFinancialBusy||state.caseBusy;return `<section class="case-section case-financial-reference"><details class="case-panel" data-case-panel="financial"${state.casePanels.financial||state.caseFinancialBusy||state.caseFinancialError?' open':''}><summary><span><strong>SAP financial reference</strong><small>${r?`Document ${esc(snapshot.documentId)} saved`:'Optional · no reference saved'}</small></span>${icon.chevron}</summary><div class="case-panel-content"><p class="case-form-copy">Query a SAP financial document and retain its returned reference in this case. It does not establish payment, booking match or refund eligibility.</p>${r?`<div class="case-financial-snapshot"><div><strong>Document ${esc(snapshot.documentId)}</strong><span class="badge neutral">Read-only SAP response</span></div><dl><div><dt>Net amount</dt><dd>${esc(money(r.totalNetAmount,r.currency))}</dd></div><div><dt>Preceding document</dt><dd>${esc(r.referenceDocument||'Not supplied')}</dd></div><div><dt>Process code</dt><dd>${esc(r.processStatusCode||'Not supplied')} · raw code</dd></div><div><dt>Approval code</dt><dd>${esc(r.approvalStatusCode||'Not supplied')}</dd></div><div><dt>Booking match</dt><dd>Not verified</dd></div><div><dt>Payment verification</dt><dd>Not performed</dd></div></dl><p>${esc(snapshot.source?.label)} · fetched ${esc(timestamp(snapshot.source?.fetchedAt||snapshot.capturedAt))}</p><p>Demonstration reference only · Refund eligibility not assessed.</p></div>`:'<p class="no-financial-reference">No SAP reference has been captured for this case.</p>'}<form id="case-financial-form"><fieldset${locked||busy||blocked?' disabled':''}><div class="field"><label for="case-financial-id">Credit memo request number</label><input id="case-financial-id" name="documentId" value="${esc(state.caseFinancialId)}" pattern="[0-9]{1,10}" inputmode="numeric" maxlength="10" required autocomplete="off"></div><div class="field"><label for="case-financial-note">Capture note <span>Required</span></label><textarea id="case-financial-note" name="note" maxlength="1000" required>${esc(state.caseFinancialNote)}</textarea></div></fieldset>${errorBlock(state.caseFinancialError,'case-financial-error')}<p class="case-financial-draft-warning"${blocked?'':' hidden'}>Save or discard the unsaved review draft before capturing a SAP reference.</p>${locked?'<p class="case-form-copy">Reopen this local review before capturing another reference.</p>':''}<button class="btn outline" id="case-financial-submit" type="submit"${locked||busy||blocked?' disabled':''}>${state.caseFinancialBusy?'Querying and saving…':'Query and save reference'} ${icon.arrow}</button><p class="fineprint">This saves the response and a local event. It does not complete any review check.</p></form></div></details><p class="case-financial-limit">Generic SAP sample only. Booking match, payment and refund eligibility are not verified.</p></section>`;}
async function captureCaseFinancialReference(){const c=state.caseData;if(!c||state.caseBusy||state.caseFinancialBusy)return;if(hasUnsavedReview()||state.caseDraftGuard){state.caseFinancialError=new Error('Save or discard the unsaved review draft first.');render();return;}if(c.reviewState==='queued'){state.caseFinancialError=new Error('Reopen this local review before capturing a reference.');render();return;}const documentId=state.caseFinancialId.trim(),note=state.caseFinancialNote.trim();if(!/^[0-9]{1,10}$/.test(documentId)||!note){state.caseFinancialError=new Error('Enter a numeric document number and a capture note.');render();return;}state.casePanels.financial=true;state.caseFinancialBusy=true;state.caseFinancialError=null;render();try{const data=await api('/api/review-cases/financial-reference',{method:'POST',body:{reference:c.request.publicReference,email:c.request.email,version:c.version,documentId,note}});const selected=applyCase(data.case);if(!selected)return;state.caseDraft=reviewDraftFrom(data.case);state.caseFinancialNote='';state.caseSuccess='SAP reference captured. Review checks and routing are unchanged.';}catch(error){if(!sameCase(state.caseData,c))return;state.caseFinancialError=error;if(error.status===409&&error.code==='REVIEW_VERSION_CONFLICT'){state.caseFinancialBusy=false;const refreshed=await loadCase({focus:false});state.caseFinancialError=new Error(refreshed?'This case changed. The latest saved review is loaded; check it before retrying the reference capture.':'This case changed, but the latest review could not be loaded. Find the case again before retrying the reference capture.');}}finally{state.caseFinancialBusy=false;if(currentView()==='staff'){render();if(sameCase(state.caseData,c))focusResult(state.caseFinancialError?'#case-financial-error':'.case-financial-reference');}}}
function financial(){if(!state.staffUnlocked)return staffGate();const h=state.health;const r=state.sapRecord;const configured=h?.sap?.configured===true;const status=h?(configured?(r?'SAP query completed.':'SAP connection configured.'):'SAP is not connected.'):state.healthError?'Connection status unavailable.':'Checking connection status…';return `${heading('Check financial document','SAP credit memo request.',false)}${operationsTabs('financial')}<div class="connection-notice">${icon.plug}<div><strong>${status}</strong><p>${configured?'Queries use the configured personal SAP connection.':'A financial document can be queried when the personal SAP connection is ready.'}</p></div><span class="badge neutral">${configured?(r?'Live response':'Ready to query'):'Not connected'}</span></div><div class="staff-layout"><div><div class="lookup-panel"><form id="document-form"><div class="field"><label for="document-reference">Credit memo request number</label><input id="document-reference" name="id" value="${esc(state.sapId)}"${state.sapLoading?' disabled':''} inputmode="numeric" pattern="[0-9]{1,10}" maxlength="10" required autocomplete="off"></div><button class="btn" type="submit"${state.sapLoading?' disabled':''}>${state.sapLoading?'Querying SAP…':'Check document'} ${icon.arrow}</button></form><p class="lookup-hint">Document 60000002 was previously verified in the SAP sandbox. No example data is loaded automatically.</p></div><div id="financial-response">${errorBlock(state.sapError)}${state.sapLoading?loading('Querying the SAP financial document…'):r?`<section class="staff-record"><div class="staff-record-head"><div><h2>Credit memo request</h2><p>${esc(r.source?.label||'SAP API response')}</p></div><strong>${esc(r.id)}</strong></div><table aria-label="SAP financial record"><tbody><tr><th scope="row">Reference document</th><td>${esc(r.referenceDocument||'Not supplied')}</td></tr><tr><th scope="row">Document category</th><td>${esc(r.referenceDocumentCategory||'Not supplied')} <span class="badge neutral">Raw SAP code</span></td></tr><tr><th scope="row">Net amount</th><td>${esc(money(r.totalNetAmount,r.currency))}</td></tr><tr><th scope="row">Process status</th><td>${esc(r.processStatusCode||'Not supplied')} <span class="badge neutral">Raw SAP code</span></td></tr><tr><th scope="row">Approval status</th><td>${esc(r.approvalStatusCode||'Not supplied')}</td></tr><tr><th scope="row">Created</th><td>${esc(r.createdAt||'Not supplied')}</td></tr></tbody></table><div class="staff-record-foot">${icon.info}<span>${esc(r.interpretation||'This financial reference does not establish approval or payment of a refund.')}</span></div></section><div class="financial-checks"><div><span>Booking link</span><strong>Not verified</strong></div><div><span>Application approval</span><strong>Not established</strong></div><div><span>Payment</span><strong>Not established</strong></div></div>`:!state.sapError?empty('No document selected','Enter a SAP credit memo request number to make a query.'):''}</div></div><aside class="staff-help"><h2>Before making a decision</h2><ul><li>Keep the local application reference and SAP document number separate.</li><li>A generic SAP sandbox document is not an Air New Zealand ticket.</li><li>A process status code does not by itself establish payment.</li></ul><div class="source-note">${icon.info}<span>Financial queries do not approve the local application or initiate a refund.</span></div></aside></div>`;}
function help(){return `${heading('Refund support','Guidance for direct bookings and travel-agent bookings.',false)}<div class="help-sheet"><section><h2>Bookings made directly</h2><p>Use the sample booking NZ7K2H and family name Taylor to try the direct-booking flow. The application is saved in this prototype and can be retrieved using its reference and email.</p></section><section><h2>Bookings made through an agent</h2><p>Try NZ8T3H and family name Taylor to see a travel-agent booking. This flow cannot create an application for that booking. The agent handling the ticket is the appropriate contact.</p></section><section><h2>What this prototype does</h2><p>It looks up sample journeys, saves applications and records local evidence checks and review handoffs. Tracking shows these saved local events. Missing review checks are tasks for the local reviewer, not an airline request for passenger documents. It does not cancel tickets, send applications to the airline, determine a refund amount or issue payment.</p></section><section><h2>Keeping your request available</h2><p>Keep the request reference and the exact email used. If a lookup fails, check both fields and retry. A request is shown only when the reference and email match.</p></section><a class="btn" href="?view=journey">Back to booking ${icon.arrow}</a></div>`;}
const views={journey,refund,review,confirmation,track,staff,financial,help};
const titles={journey:'My journey',refund:'Refund request',review:'Review request',confirmation:'Request saved',track:'Track request',staff:'Staff review',financial:'SAP financial reference',help:'Help & guidance'};
function render(){const requested=currentView();const view=views[requested]?requested:'journey';const hadResultFocus=view==='confirmation'&&main.contains(document.activeElement);main.innerHTML=views[view]();document.querySelector('#context-page').textContent=titles[view];document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===view||(a.dataset.nav==='refund'&&['review','confirmation'].includes(view))||(a.dataset.nav==='staff'&&view==='financial');if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const pageTitle=view==='confirmation'?(state.request?(state.creationResult?.created===false?'Existing application':state.creationResult?.created===true?'Request saved':'Saved application'):'Your refund request'):titles[view];document.title=`AirAssist · ${pageTitle}`;bindForms();bindCaseForms();if(hadResultFocus)focusResult('.success-sheet h2');}
function bindForms(){const gate=document.querySelector('#staff-gate-form');if(gate){gate.addEventListener('submit',event=>{event.preventDefault();state.staffCode=gate.elements.code.value.trim();requestQueue({verifying:true});});gate.addEventListener('input',()=>{state.staffCode=gate.elements.code.value;state.staffError=null;});}document.querySelector('#lock-staff')?.addEventListener('click',()=>lockStaff());bindQueue();const b=document.querySelector('#booking-lookup');if(b){b.addEventListener('input',()=>{state.lookup.reference=b.elements.reference.value.trim().toUpperCase();state.lookup.lastName=b.elements.lastName.value;clearReadInput('booking');persist()});b.addEventListener('submit',e=>{e.preventDefault();state.lookup.reference=b.elements.reference.value.trim().toUpperCase();state.lookup.lastName=b.elements.lastName.value.trim();persist();loadBooking({focus:true})});}const f=document.querySelector('#refund-form');if(f){const capture=()=>{const data=new FormData(f);updateDraft({email:String(data.get('email')||''),reason:String(data.get('reason')||''),details:String(data.get('details')||'')})};f.addEventListener('input',capture);f.addEventListener('change',capture);f.addEventListener('submit',e=>{e.preventDefault();capture();state.submitError=null;state.acknowledged=false;navigate('?view=review')});}const submit=document.querySelector('#submit-request');if(submit){const ack=document.querySelector('#request-acknowledgment');ack.addEventListener('change',()=>{state.acknowledged=ack.checked;document.querySelector('#submit-button').disabled=state.submitting||!state.acknowledged});submit.addEventListener('submit',e=>{e.preventDefault();if(state.submitting)return;if(!ack.checked){ack.reportValidity();return;}state.acknowledged=true;submitRequest()});}const t=document.querySelector('#track-form');if(t){t.addEventListener('input',()=>{state.track.reference=t.elements.reference.value;state.track.email=t.elements.email.value;clearReadInput('track');});t.addEventListener('submit',e=>{e.preventDefault();state.track.reference=t.elements.reference.value.trim().toUpperCase();state.track.email=t.elements.email.value.trim();lookupRequest()});}document.querySelector('#use-saved-request')?.addEventListener('click',()=>{state.track={...state.lastRequest};lookupRequest()});const d=document.querySelector('#document-form');if(d){d.addEventListener('input',()=>{state.sapId=d.elements.id.value;clearReadInput('financial');});d.addEventListener('submit',e=>{e.preventDefault();state.sapId=d.elements.id.value.trim();lookupFinancialDocument()});}document.querySelector('[data-download-receipt]')?.addEventListener('click',()=>{const r=currentView()==='confirmation'?state.request:state.trackRecord;if(r)downloadReceipt(r);});document.querySelector('[data-copy-reference]')?.addEventListener('click',async e=>{try{await navigator.clipboard.writeText(e.currentTarget.dataset.copyReference);toast('Request reference copied.');}catch{toast('Select the reference to copy it manually.');}});}
function updateDraft(next){const changed=['email','reason','details'].some(k=>next[k]!==state.draft[k]);if(changed){state.draft={...state.draft,...next,requestKey:newKey()};state.acknowledged=false;state.submitError=null;persist();}}
function clearReadInput(name){readQueries.cancel(name);if(name==='booking'){state.booking=null;state.bookingError=null;state.bookingLoading=false;document.querySelector('.booking-context')?.setAttribute('hidden','');}if(name==='track'){state.trackRecord=null;state.trackError=null;state.trackLoading=false;state.trackAutoAttempted=true;}if(name==='financial'){state.sapRecord=null;state.sapError=null;state.sapLoading=false;}document.querySelector(`#${name}-response`)?.setAttribute('hidden','');}
async function loadBooking({focus=false}={}){const query={reference:state.lookup.reference.trim().toUpperCase(),lastname:state.lookup.lastName.trim()};const ticket=readQueries.start('booking',query);const oldReference=state.booking?.reference;state.bookingLoading=true;state.bookingError=null;state.booking=null;render();try{const data=await api('/api/bookings?'+new URLSearchParams(ticket.query),{signal:ticket.signal});if(!ticket.current())return;state.booking=data.booking;if(oldReference&&oldReference!==data.booking.reference){state.draft.requestKey=newKey();state.acknowledged=false;state.submitError=null;persist();}}catch(error){if(ticket.current())state.bookingError=error;}finally{if(ticket.current()){state.bookingLoading=false;ticket.finish();if(['journey','refund','review'].includes(currentView()))render();if(focus&&currentView()==='journey')focusResult(state.bookingError?'.app-error':'.ticket');}}}
async function submitRequest(){if(state.submitting||!state.booking||state.booking.channel!=='direct'||!state.acknowledged)return;state.submitting=true;state.submitError=null;persist();render();try{const data=await api('/api/refund-requests',{method:'POST',body:{bookingReference:state.booking.reference,lastName:state.booking.lastName,email:state.draft.email.trim(),reason:state.draft.reason,details:state.draft.details.trim(),acknowledged:true,requestKey:state.draft.requestKey}});state.request=data.request;state.creationResult={created:typeof data.created==='boolean'?data.created:null,message:String(data.message||'')};state.lastRequest={reference:data.request.publicReference,email:data.request.email};state.track={...state.lastRequest};state.trackRecord=null;state.trackAutoAttempted=false;persist();state.submitting=false;navigate('?view=confirmation');focusResult('.success-sheet h2');}catch(error){state.submitError=error;state.submitting=false;render();focusResult('.app-error');document.querySelector('.app-error')?.scrollIntoView({block:'nearest'});}}
async function lookupRequest({confirmation=false,focus=true}={}){const query={reference:state.track.reference.trim().toUpperCase(),email:state.track.email.trim()};const ticket=readQueries.start('track',query);state.trackLoading=true;state.trackError=null;state.trackRecord=null;state.trackAutoAttempted=true;render();try{const data=await api('/api/refund-requests?'+new URLSearchParams(ticket.query),{signal:ticket.signal});if(!ticket.current())return;state.trackRecord=data.request;if(confirmation)state.request=data.request;state.lastRequest={reference:data.request.publicReference,email:data.request.email};persist();}catch(error){if(ticket.current())state.trackError=error;}finally{if(ticket.current()){state.trackLoading=false;ticket.finish();if(['track','confirmation'].includes(currentView()))render();if(focus&&['track','confirmation'].includes(currentView()))focusResult(state.trackError?'.app-error':currentView()==='confirmation'?'.success-sheet h2':'.tracking-top');}}}
async function loadHealth(){try{state.health=await api('/api/health');state.healthError=false;}catch{state.healthError=true;}if(currentView()==='financial')render();}
async function lookupFinancialDocument(){const ticket=readQueries.start('financial',{id:state.sapId.trim()});state.sapLoading=true;state.sapRecord=null;state.sapError=null;render();try{const data=await api('/api/sap/credit-memo-requests?'+new URLSearchParams(ticket.query),{signal:ticket.signal});if(!ticket.current())return;state.sapRecord=data.record;state.health={...(state.health||{}),sap:{...(state.health?.sap||{}),mode:'live',configured:true,accountPolicy:'personal-only'}};}catch(error){if(ticket.current())state.sapError=error;}finally{if(ticket.current()){state.sapLoading=false;ticket.finish();if(currentView()==='financial'){render();focusResult(state.sapError?'.app-error':'.staff-record-head');}}}}
function cancelReadViews(next){if(!['journey','refund','review'].includes(next)){readQueries.cancel('booking');state.bookingLoading=false;}if(!['track','confirmation'].includes(next)){readQueries.cancel('track');if(state.trackLoading)state.trackAutoAttempted=false;state.trackLoading=false;}if(next!=='financial'){readQueries.cancel('financial');state.sapLoading=false;}if(next!=='staff'){readQueries.cancel('case');if(state.caseLoading)state.caseAutoAttempted=false;state.caseLoading=false;}if(!['staff','financial'].includes(next)){readQueries.cancel('queue');state.queueLoading=false;}}
function ensureViewData(){const view=currentView();if(['staff','financial'].includes(view)&&!state.staffUnlocked&&!state.staffAutoAttempted&&state.staffCode){state.staffAutoAttempted=true;requestQueue({verifying:true});}if(['journey','refund','review'].includes(view)&&!state.booking&&!state.bookingError&&!state.bookingLoading)loadBooking();if((view==='track'||view==='confirmation')&&state.track.reference&&state.track.email&&!state.trackAutoAttempted&&!state.trackLoading){lookupRequest({confirmation:view==='confirmation',focus:false});}if(view==='financial')loadHealth();if(view==='staff'&&state.caseLookup.reference&&state.caseLookup.email&&!state.caseAutoAttempted&&!state.caseLoading)loadCase({focus:false});}
function focusResult(selector){const target=document.querySelector(selector);if(target){target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}}
function navigate(href){cancelReadViews(new URLSearchParams(href.split('?')[1]||'').get('view')||'journey');history.pushState({},'',href);render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});ensureViewData();}
function toast(message){document.querySelector('.toast')?.remove();const item=document.createElement('div');item.className='toast';item.setAttribute('role','status');item.textContent=message;document.body.appendChild(item);setTimeout(()=>item.remove(),4500);}
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="?view="]');if(!link||e.ctrlKey||e.metaKey||e.altKey||e.shiftKey)return;e.preventDefault();if(link.getAttribute('aria-disabled')==='true'||state.submitting){toast('Your application is being saved. Please wait.');return;}navigate(link.getAttribute('href'));});
window.addEventListener('popstate',()=>{cancelReadViews(currentView());render();ensureViewData();});render();requestAnimationFrame(()=>window.scrollTo({top:0,left:0,behavior:'instant'}));loadHealth();loadBooking();ensureViewData();
